/* Hot-load the actual v2 frontend/YM payload after a live demo. The included
 * state API is extracted byte-for-byte from current generated web source;
 * SDL presentation rebasing/queued-audio calls alone are harmless native stubs. */
#define GENESIS_NO_MAIN
#include "../.local/source/build/dune-base.c"
#include "em_web_menu_select.h"
#define EM_WEB_BUILDING_UI_NO_EXPORTS
#include "em_web_building_ui.h"
#include "em_web_campaign.h"
#define EMSCRIPTEN_KEEPALIVE
static CPU em_cpu,before;static int em_window=1;
static struct {DuneMouse dune_mouse;struct{int camera_valid;uint64_t frame;}dune_view;uint64_t next_service,last_frame;int stopped,audio_device,audio_running;}em_host;
static void sdl_host_rebase(void*h,const CPU*c){(void)h;(void)c;}
static void SDL_ClearQueuedAudio(int device){(void)device;}
#include "../.local/campaign-analysis/native-state-api.inc"
_Static_assert(sizeof(DuneSaveState)==140056,"current portable v2 ABI");
static uint8_t world_save[256*1024],world_ram[65536];static uint64_t report_frame=UINT64_MAX;static size_t max_json;
static void check(int ok,const char*msg){if(!ok){fprintf(stderr,"FAIL %s pc=%06x z80=%04x head=%02x%02x%02x %s reason=%s\n",msg,em_cpu.pc,em_cpu.z80_cpu.pc,em_cpu.z80_bus.ram[0],em_cpu.z80_bus.ram[1],em_cpu.z80_bus.ram[2],em_web_campaign_report(&em_cpu),em_cpu.reason?em_cpu.reason:"");exit(1);}}
static void load(const char*path){FILE*f=fopen(path,"rb");check(f!=NULL,"v2 fixture open");size_t n=fread(g_dune_state_buffer,1,sizeof g_dune_state_buffer,f);check(feof(f)&&!ferror(f),"v2 fixture bounded read");fclose(f);check(dune_load_state_from_buffer((int)n),"actual original v2 loader");report_frame=UINT64_MAX;}
static void step(void){if(!em_web_campaign_observe(&em_cpu))dune_mouse_observe(&em_host.dune_mouse,&em_cpu);machine_step(&em_cpu);check(!em_cpu.fault,"native AUDIO_ON playback");if(em_cpu.vdp.frames%3==0&&report_frame!=em_cpu.vdp.frames){report_frame=em_cpu.vdp.frames;before=em_cpu;const char*a=em_web_campaign_report(&em_cpu),*b=em_web_building_ui_json_for(&em_cpu,&em_web_menu_select);size_t na=strlen(a),nb=strlen(b);if(na>max_json)max_json=na;if(nb>max_json)max_json=nb;check(na<4096&&nb<32768,"browser-like report bounds");check(!memcmp(&before,&em_cpu,sizeof em_cpu),"browser-like getters do not mutate CPU");}}
static void frames(unsigned n){uint64_t end=em_cpu.vdp.frames+n;while(em_cpu.vdp.frames<end)step();}
static void wait_ready(const char*scene,unsigned budget){uint64_t end=em_cpu.vdp.frames+budget;while((!em_web_campaign.scene||strcmp(em_web_campaign.scene,scene)||!em_web_campaign_scene_ready(&em_cpu))&&em_cpu.vdp.frames<end)step();check(em_web_campaign.scene&&!strcmp(em_web_campaign.scene,scene)&&em_web_campaign_scene_ready(&em_cpu),"real completed native destination");}
static void route(int target){check(em_web_campaign_route_request(&em_cpu,target),"safe native route");uint64_t end=em_cpu.vdp.frames+5000;while(em_web_campaign.route_pending&&em_cpu.vdp.frames<end)step();check(!em_web_campaign.route_pending,"safe route completed");wait_ready(em_web_campaign_route_name(target),200);}
static void toggle(int row){check(em_web_campaign_input_request(&em_cpu,2,row),"native settings value Right");uint64_t end=em_cpu.vdp.frames+300;while(em_web_campaign.input_pending&&em_cpu.vdp.frames<end)step();check(!em_web_campaign.input_pending,"native toggle consumed once");frames(8);}
int main(int argc,char**argv){check(argc==3,"usage FRONTEND_V2 DEMO_V2");em_cpu.rom=rom_data;em_cpu.rom_size=sizeof rom_data;em_cpu.audio_mode=AUDIO_ON;check(audio_init(&em_cpu,NULL),"real YMFM initialized");em_host.dune_mouse.enabled=1;
 load(argv[1]);wait_ready("main",30);check(em_web_campaign_house(&em_cpu)==-1&&dune_long(&em_cpu,0xc278)==0,"frontend is genuine no-house main");route(2);frames(60);route(0);route(1);toggle(0);toggle(1);check(!em_cpu.ram[0xdc50]&&!em_cpu.ram[0xdc51],"both options OFF through original handlers");route(0);check(!em_cpu.ram[0xdc50]&&!em_cpu.ram[0xdc51],"clean Options Back retains native OFF/OFF");puts("PASS full YM frontend -> Tutorial/Back -> Options OFF/OFF -> native main retains settings");fflush(stdout);
 load(argv[2]);wait_ready("map",30);route(3);check(em_web_campaign_input_request(&em_cpu,1,6),"original Restart confirmation");uint64_t end=em_cpu.vdp.frames+300;while(em_web_campaign.input_pending&&em_cpu.vdp.frames<end)step();wait_ready("confirm",300);check(em_web_campaign_input_request(&em_cpu,5,1),"original Restart No");end=em_cpu.vdp.frames+300;while(em_web_campaign.input_pending&&em_cpu.vdp.frames<end)step();wait_ready("pause",300);route(4);frames(20);int n=dune_save_state_to_buffer();check(n>140056,"real world save includes YMFM");memcpy(world_save,g_dune_state_buffer,n);memcpy(world_ram,em_cpu.ram,sizeof world_ram);for(int t=0;t<3;t++){before=em_cpu;check(!em_web_campaign_route_request(&em_cpu,t),"world cannot borrow startup main/options/tutorial");check(!memcmp(&before,&em_cpu,sizeof em_cpu),"unsafe route rejection leaves world exact");}
 load(argv[1]);wait_ready("main",30);em_web_campaign.frontend_hold=1;frames(6000);check(em_web_campaign.scene&&!strcmp(em_web_campaign.scene,"main")&&em_web_campaign.attract_counter_resets>2700,"hot world -> clean frontend keeps native main past three attract windows");check(!em_web_campaign.ui_call_active,"no borrowed world UI stack exists");route(1);toggle(0);toggle(1);route(0);check(!em_cpu.ram[0xdc50]&&!em_cpu.ram[0xdc51],"restored preference flow retains OFF/OFF");route(2);frames(60);route(0);check(!em_cpu.ram[0xdc50]&&!em_cpu.ram[0xdc51],"Tutorial Back also preserves OFF/OFF");puts("PASS hot YM0 demo -> pause/restartNo/resume -> full YM frontend -> idle6000 -> Options/Tutorial, no Z80 fault");fflush(stdout);
 memcpy(g_dune_state_buffer,world_save,n);check(dune_load_state_from_buffer(n),"normal Continue world load");check(!memcmp(world_ram,em_cpu.ram,sizeof world_ram),"Continue restores every original world RAM byte");wait_ready("map",30);check(em_web_campaign.armed&&!em_web_campaign.outcome_seq,"Continue arms actual world without completion");puts("PASS Continue world save exact RAM/YM, zero false outcome");fflush(stdout);
 load(argv[1]);wait_ready("main",30);check(em_web_campaign_request(&em_cpu,1,1),"campaign from clean frontend");end=em_cpu.vdp.frames+6000;while(em_web_campaign.stage!=4&&em_cpu.vdp.frames<end)step();check(em_web_campaign.stage==4,"original new-house initialization");frames(400);check(em_web_campaign.pending&&!em_web_campaign.starts,"requested briefing remains manual");end=em_cpu.vdp.frames+6000;uint64_t next=em_cpu.vdp.frames;while(em_web_campaign.pending&&em_cpu.vdp.frames<end){if(em_cpu.vdp.frames>=next&&em_web_campaign.poll_frame+3>=em_cpu.vdp.frames&&!em_web_campaign.input_pending){em_web_campaign_input_request(&em_cpu,em_web_campaign.poll_pc==0x25cb2?5:0,em_web_campaign.poll_pc==0x25cb2?0:PAD_A);next=em_cpu.vdp.frames+45;}step();}check(!em_web_campaign.pending&&em_web_campaign.starts==1&&em_web_campaign_house(&em_cpu)==1&&em_web_campaign_mission(&em_cpu)==1&&!em_web_campaign.outcome_seq,"native Atreides1 scenario starts from genuine frontend");printf("PASS clean full-YM frontend -> original campaign; browser-like report max %zu bytes, whole-CPU immutable\n",max_json);audio_finish(&em_cpu);return 0;}
